  mutate(change = sbp_12 - sbp_0) |&gt;
  group_by(arm) |&gt;
  summarise(
    n_eligible = n(),
    n_observed = sum(!is.na(change)),
    mean_change = mean(change, na.rm = TRUE),
    .groups = "drop"
